const basePremiumOf = (item: Item): number =>
  BASE_PREMIUM_BY_ITEM_TYPE[item.type];

const policyBasePremiumOf = (items: readonly Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOf(item), 0);

export function runScenario(scenario: Scenario): ScenarioResult {
  const quoteStep = scenario.steps[0] as QuoteStep;
  const premium = policyBasePremiumOf(quoteStep.items) + PROCESSING_FEE;
  return { results: [{ premium }] };
}
